INSERT INTO "FOOD"("PRICE", "CATEGORY_ID", "ID", "DESCRIPTION", "RECEPT", "ALLERGEN_SHEET_FILE_NAME", "CURRENCY", "NAME") VALUES(9.00, '174c50b2-e9ef-3dbe-868b-4fcb2f97d4a3', 'cce99657-d3bb-3f90-9a8e-66aa40bc5684', 'Our artichokes are brushed with an olive, oil, and rosemary blend, and then broiled to perfection. Served with a side of creamy garlic aioli.', NULL, NULL, 'USD', 'Artichokes with Garlic Aioli');
INSERT INTO "FOOD"("PRICE", "CATEGORY_ID", "ID", "DESCRIPTION", "RECEPT", "ALLERGEN_SHEET_FILE_NAME", "CURRENCY", "NAME") VALUES(7.00, '174c50b2-e9ef-3dbe-868b-4fcb2f97d4a3', 'e8608782-c427-33f4-b292-c09fddab3d8c', 'Caramelized onions slow cooked in a savory broth topped with sourdough, and a provolone cheese blend. Served with sourdough bread.', NULL, NULL, 'USD', 'French Onion Soup');
INSERT INTO "FOOD"("PRICE", "CATEGORY_ID", "ID", "DESCRIPTION", "RECEPT", "ALLERGEN_SHEET_FILE_NAME", "CURRENCY", "NAME") VALUES(8.00, '174c50b2-e9ef-3dbe-868b-4fcb2f97d4a3', '4aa95576-ca34-3d9b-9491-4e81be9d4be9', 'These mini cheeseburgers are served on a fresh baked pretzel bun with lettuce, tomato, avocado, and your choice of cheese.', NULL, NULL, 'USD', 'Mini Cheeseburgers');
INSERT INTO "FOOD"("PRICE", "CATEGORY_ID", "ID", "DESCRIPTION", "RECEPT", "ALLERGEN_SHEET_FILE_NAME", "CURRENCY", "NAME") VALUES(7.00, '174c50b2-e9ef-3dbe-868b-4fcb2f97d4a3', '75c3df39-8592-3704-b6c5-f6da9dd5d8a7', 'Large mushroom caps are filled a savory cream cheese, bacon and panko breadcrumb stuffing" topped with cheddar cheese.', NULL, NULL, 'USD', 'Panko Stuffed Mushrooms');
INSERT INTO "FOOD"("PRICE", "CATEGORY_ID", "ID", "DESCRIPTION", "RECEPT", "ALLERGEN_SHEET_FILE_NAME", "CURRENCY", "NAME") VALUES(7.00, '22c9a842-895a-3e9e-b5a6-fe369d9db01a', '9cbf0167-7ca0-3a21-807b-86c191e3e150', 'Our house salad is made with romaine lettuce and spinach, topped with tomatoes, cucumbers, red onions and carrots, Served with a dressing of your choice.', NULL, NULL, 'USD', 'House Salad');
INSERT INTO "FOOD"("PRICE", "CATEGORY_ID", "ID", "DESCRIPTION", "RECEPT", "ALLERGEN_SHEET_FILE_NAME", "CURRENCY", "NAME") VALUES(9.00, '22c9a842-895a-3e9e-b5a6-fe369d9db01a', 'a49d04c2-ff97-301f-9801-bbe5bdf330c9', 'The chef''s salad has cucumber, tomatoes, red onions, mushrooms, hard-boiled eggs, cheese, and hot grilled chicken on a bed of romaine lettuce. Served with croutons and your choice of dressing.', NULL, NULL, 'USD', 'Chef''s Salad');
INSERT INTO "FOOD"("PRICE", "CATEGORY_ID", "ID", "DESCRIPTION", "RECEPT", "ALLERGEN_SHEET_FILE_NAME", "CURRENCY", "NAME") VALUES(9.99, '22c9a842-895a-3e9e-b5a6-fe369d9db01a', '866cdefc-28e8-3ec7-8804-8ecd3d96ca8b', 'Our quinoa salad is served with quinoa, tomatoes, cucumber, scallions, and smoked salmon. Served with your choice of dressing.', NULL, NULL, 'USD', 'Quinoa Salmon Salad');
INSERT INTO "FOOD"("PRICE", "CATEGORY_ID", "ID", "DESCRIPTION", "RECEPT", "ALLERGEN_SHEET_FILE_NAME", "CURRENCY", "NAME") VALUES(9.99, '1520fbfc-06bd-3044-8ccd-7af44e216d6c', 'e0f2873e-fee2-3ef6-955c-39fddd68a387', 'Our classic burger is made with 100% pure angus beef, served with lettuce, tomatoes, onions, pickles, and cheese of your choice. Veggie burger available upon request. Served with French fries, fresh fruit, or a side salad.', NULL, NULL, 'USD', 'Classic Burger');
INSERT INTO "FOOD"("PRICE", "CATEGORY_ID", "ID", "DESCRIPTION", "RECEPT", "ALLERGEN_SHEET_FILE_NAME", "CURRENCY", "NAME") VALUES(9.99, '1520fbfc-06bd-3044-8ccd-7af44e216d6c', 'e271a857-0a42-3adb-af79-802bbcc4af85', 'This classic cheese tortellini is cooked in a sundried tomato sauce. Served with bruschetta topped with a tomato and basil marinara.', NULL, NULL, 'USD', 'Tomato Bruschetta Tortellini');
INSERT INTO "FOOD"("PRICE", "CATEGORY_ID", "ID", "DESCRIPTION", "RECEPT", "ALLERGEN_SHEET_FILE_NAME", "CURRENCY", "NAME") VALUES(9.99, '1520fbfc-06bd-3044-8ccd-7af44e216d6c', '4b86f825-489c-3e5f-b5f7-e1fa1b55210d', 'Our thin crust pizzas are made fresh daily and topped with your choices of fresh meats, veggies, cheese, and sauce,  Price includes two toppings. Add $1 for each additional topping.', NULL, NULL, 'USD', 'Handcrafted Pizza');
INSERT INTO "FOOD"("PRICE", "CATEGORY_ID", "ID", "DESCRIPTION", "RECEPT", "ALLERGEN_SHEET_FILE_NAME", "CURRENCY", "NAME") VALUES(9.99, '1520fbfc-06bd-3044-8ccd-7af44e216d6c', 'b5d1ef80-f972-3328-88e3-1fa259f23106', 'Our barbecued skewers include tofu, cherry tomatoes, bell peppers, and zucchini marinated in a ginger sesame sauce and charbroiled. Served with steamed rice.', NULL, NULL, 'USD', 'Barbecued Tofu Skewers');
INSERT INTO "FOOD"("PRICE", "CATEGORY_ID", "ID", "DESCRIPTION", "RECEPT", "ALLERGEN_SHEET_FILE_NAME", "CURRENCY", "NAME") VALUES(9.00, 'd5cdf61f-a211-3c1a-ae5c-8ed26fb8978b', '5d4e4372-f5ba-30a0-940a-8b95e9355b21', 'Elegantly crafted creamy vanilla custard with a caramelized crunchy layer on top. Served with seasonal fruit.', NULL, NULL, 'USD', 'Creme Brulee');
